
/**
 * Product Catalog Constants
 *
 * Product Type: Simple + Variable
 * SKU: Auto-generated
 * Image Storage: Cloudinary
 * Cost Price: Private batched Firestore documents
 */

// ==============================
// PRODUCT TYPE
// ==============================

export const PRODUCT_TYPE = Object.freeze({
  SIMPLE: "simple",
  VARIABLE: "variable"
});

// ==============================
// PRODUCT STATUS
// ==============================

export const PRODUCT_STATUS = Object.freeze({
  DRAFT: "draft",
  ACTIVE: "active",
  INACTIVE: "inactive"
});

// ==============================
// PRODUCT DEFAULTS
// ==============================

export const PRODUCT_DEFAULTS = Object.freeze({
  TYPE: PRODUCT_TYPE.SIMPLE,
  STATUS: PRODUCT_STATUS.DRAFT,

  BRAND: "Nishat Fashion",

  FEATURED: false,

  TRACK_INVENTORY: true,
  ALLOW_BACKORDER: false,
  REQUIRES_SHIPPING: true
});

// ==============================
// PRODUCT SKU
// ==============================

/**
 * Example:
 * NF-000001
 * NF-000002
 *
 * SKU is generated by the backend.
 */

export const PRODUCT_SKU = Object.freeze({
  PREFIX: "NF",
  START_NUMBER: 1,
  MIN_DIGITS: 6
});

// ==============================
// PRODUCT IMAGES
// ==============================

/**
 * Product images are stored in Cloudinary.
 *
 * Firestore stores only image URLs and metadata.
 */

export const PRODUCT_IMAGES = Object.freeze({
  STORAGE_PROVIDER: "cloudinary",

  MAX_IMAGES: 20,
  MIN_IMAGES: 1,

  ALLOWED_FORMATS: Object.freeze([
    "jpg",
    "jpeg",
    "png",
    "webp"
  ])
});

// ==============================
// PRODUCT VARIANTS
// ==============================

/**
 * Each Variant must have a permanent unique variantId.
 *
 * Variant Cost Price is linked using variantId,
 * not color or size text.
 */

export const PRODUCT_VARIANTS = Object.freeze({
  MAX_VARIANTS: 200,

  ATTRIBUTES: Object.freeze([
    "color",
    "size"
  ])
});

// ==============================
// PRIVATE COST PRICE
// ==============================

/**
 * Cost Price must never be stored inside:
 *
 * products/{productId}
 *
 * Private batch structure:
 *
 * private/{randomBatchId}
 *
 * {
 *   productCosts: {
 *     productId_001: {
 *       cost: 300,
 *       variants: {
 *         variantId_red_m: 200,
 *         variantId_blue_l: 250
 *       }
 *     },
 *
 *     productId_002: {
 *       cost: 350,
 *       variants: {}
 *     }
 *   },
 *
 *   updatedAt: timestamp
 * }
 *
 * Each batch document can contain up to 300 Product entries.
 */

export const PRODUCT_COSTS = Object.freeze({
  COLLECTION: "private",

  BATCH_SIZE: 300,

  FIELD_NAME: "productCosts",

  PRODUCT_COST_FIELD: "cost",

  VARIANT_COST_FIELD: "variants"
});

// ==============================
// GEMINI TEXT FIELDS
// ==============================

/**
 * Gemini can generate only these Product text fields:
 *
 * 1. Short Description
 * 2. Full Description
 * 3. Tags
 *
 * Prompts will be stored separately.
 */

export const PRODUCT_TEXT_FIELDS = Object.freeze({
  SHORT_DESCRIPTION: "shortDescription",

  FULL_DESCRIPTION: "fullDescription",

  TAGS: "tags"
});

// ==============================
// PRODUCT LIMITS
// ==============================

export const PRODUCT_LIMITS = Object.freeze({
  NAME_MAX_LENGTH: 200,

  SLUG_MAX_LENGTH: 200,

  SHORT_DESCRIPTION_MAX_LENGTH: 500,

  FULL_DESCRIPTION_MAX_LENGTH: 10000,

  MAX_TAGS: 30,

  TAG_MAX_LENGTH: 50
});

// ==============================
// PRODUCT TAXONOMY FIELDS
// ==============================

/**
 * These IDs must reference existing taxonomy records.
 */

export const PRODUCT_TAXONOMY_FIELDS = Object.freeze({
  COLLECTION_ID: "collectionId",

  CATEGORY_ID: "categoryId",

  SUBCATEGORY_ID: "subcategoryId"
});
